-- Phase 10K2 disposable assertions. Every PASS line is counted by the verifier.
create or replace function phase10k2_test.assert(input_condition boolean,input_label text)
returns void language plpgsql as $$
begin
  if not coalesce(input_condition,false) then raise exception 'FAIL %',input_label; end if;
  raise notice 'PASS %',input_label;
end $$;

select phase10k2_test.assert((select ui_release_stage='manager_preview' from public.routine_organization_settings where organization_id='a1000000-0000-4000-8000-000000000001'),'001 release stage is manager_preview');
select phase10k2_test.assert((select ui_contract_version='phase10k2-v1' from public.routine_organization_settings where organization_id='a1000000-0000-4000-8000-000000000001'),'002 K2 contract version installed');
select phase10k2_test.assert((select mode='shadow' from public.routine_organization_settings where organization_id='a1000000-0000-4000-8000-000000000001'),'003 explicit K1 fixture mode remains shadow');
select phase10k2_test.assert((select value is not null from phase10k2_test.state where key='foundation'),'004 foundation read model returned');
select phase10k2_test.assert((select jsonb_typeof(value->'locations')='array' from phase10k2_test.state where key='foundation'),'005 locations are structured');
select phase10k2_test.assert((select jsonb_typeof(value->'locationSets')='array' from phase10k2_test.state where key='foundation'),'006 location sets are structured');
select phase10k2_test.assert((select jsonb_typeof(value->'standards')='array' from phase10k2_test.state where key='foundation'),'007 standards are structured');
select phase10k2_test.assert((select value ? 'revisionNumbers' from phase10k2_test.state where key='foundation'),'008 foundation revisions returned');
select phase10k2_test.assert((select value->'template'->>'routine_key'='daily-run-test' from phase10k2_test.state where key='editor'),'009 editor is tenant scoped');
select phase10k2_test.assert((select value->'version'->>'state'='draft' from phase10k2_test.state where key='editor'),'010 draft selected');
select phase10k2_test.assert((select (value->>'immutable')::boolean=false from phase10k2_test.state where key='editor'),'011 draft is editable');
select phase10k2_test.assert((select jsonb_typeof(value->'sections')='array' from phase10k2_test.state where key='editor'),'012 sections structured');
select phase10k2_test.assert((select jsonb_typeof(value->'tasks')='array' from phase10k2_test.state where key='editor'),'013 tasks structured');
select phase10k2_test.assert((select jsonb_typeof(value->'taskItems')='array' from phase10k2_test.state where key='editor'),'014 items structured');
select phase10k2_test.assert((select jsonb_typeof(value->'dependencies')='array' from phase10k2_test.state where key='editor'),'015 dependencies structured');
select phase10k2_test.assert((select jsonb_typeof(value->'relations')='array' from phase10k2_test.state where key='editor'),'016 relations structured');
select phase10k2_test.assert((select jsonb_typeof(value->'referenceLinks')='array' from phase10k2_test.state where key='editor'),'017 links structured');
select phase10k2_test.assert((select value ? 'validation' from phase10k2_test.state where key='editor'),'018 authoritative validation returned');
select phase10k2_test.assert((select value ? 'currentPublishedSummary' from phase10k2_test.state where key='editor'),'019 current published summary returned');
select phase10k2_test.assert((select value->'metadataChanges' @> '[{"field":"name"}]'::jsonb from phase10k2_test.state where key='diff'),'020 diff reports metadata name');
select phase10k2_test.assert((select value ? 'sections' and value ? 'tasks' and value ? 'taskItems' from phase10k2_test.state where key='diff'),'021 diff is structured by entity');
select phase10k2_test.assert((select value ? 'timingPolicyChanges' from phase10k2_test.state where key='diff'),'022 timing policy diff returned');
select phase10k2_test.assert((select value->'contentHashes' ? 'from' and value->'contentHashes' ? 'to' from phase10k2_test.state where key='diff'),'023 diff contains both content hashes');
select phase10k2_test.assert((select jsonb_array_length(value->'versions')=1 from phase10k2_test.state where key='preview'),'024 single preview uses batch model');
select phase10k2_test.assert((select value ? 'publicationOrder' from phase10k2_test.state where key='preview'),'025 publication order returned');
select phase10k2_test.assert((select value ? 'crossTemplateRelations' from phase10k2_test.state where key='preview'),'026 cross-template relations returned');
select phase10k2_test.assert((select jsonb_typeof(value->'blockers')='array' and jsonb_typeof(value->'warnings')='array' from phase10k2_test.state where key='preview'),'027 blockers and warnings returned');
select phase10k2_test.assert((select jsonb_typeof(value->'references')='array' from phase10k2_test.state where key='references'),'028 references structured');
select phase10k2_test.assert((select value ? 'pendingSummary' and value ? 'cleanupSummary' from phase10k2_test.state where key='references'),'029 upload summaries returned');
select phase10k2_test.assert((select jsonb_typeof(value->'usage')='array' from phase10k2_test.state where key='references'),'030 usage returned');
select phase10k2_test.assert((select value->'categories' ? 'operationalContent' from phase10k2_test.state where key='readiness'),'031 operational content readiness exists');
select phase10k2_test.assert((select jsonb_array_length(value->'categories'->'operationalContent'->'blockers')>0 from phase10k2_test.state where key='readiness'),'032 O C DS blocker exists');
select phase10k2_test.assert((select (value->>'ready')::boolean=false from phase10k2_test.state where key='readiness'),'033 K2 never marks release ready');
select phase10k2_test.assert((select not (value ? 'generatedAt') from phase10k2_test.state where key='readiness'),'034 readiness read is timestamp deterministic');
select phase10k2_test.assert((select value->>'contractVersion'='phase10k2-v1' from phase10k2_test.state where key='control_center'),'035 control center contract returned');
select phase10k2_test.assert((select value ? 'applicationBootstrap' and value ? 'releaseReadiness' from phase10k2_test.state where key='control_center'),'036 complete control center returned');
select phase10k2_test.assert((select value->'operatorAdministration' ? 'devices' from phase10k2_test.state where key='control_center'),'037 operator workspace returned');
select phase10k2_test.assert((select value->'pilotAccess' ? 'memberships' from phase10k2_test.state where key='control_center'),'038 pilot workspace returned');
select phase10k2_test.assert((select value='true'::jsonb from phase10k2_test.state where key='staff_rejected'),'039 staff rejected');
select phase10k2_test.assert((select value='true'::jsonb from phase10k2_test.state where key='shared_rejected'),'040 shared operator rejected');
select phase10k2_test.assert((select value='true'::jsonb from phase10k2_test.state where key='cross_org_rejected'),'041 cross organization rejected');
select phase10k2_test.assert(not exists(select 1 from phase10k2_test.state where value::text ~* 'pin_hash|session_secret_hash|creation_request_hash'),'042 read models contain no secret hashes');
select phase10k2_test.assert(not exists(select 1 from phase10k2_test.state where value::text ~* 'sessionToken|operatorSessionToken|rawOperations'),'043 read models contain no token or raw operations');
select phase10k2_test.assert((select count(*)=7 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('get_routine_manager_control_center','get_routine_foundation_editor_workspace','get_routine_template_editor_workspace','get_routine_template_version_diff','preview_routine_template_publication_batch','get_routine_reference_manager_workspace','get_routine_release_readiness')),'044 seven manager read RPCs installed');
select phase10k2_test.assert(not exists(select 1 from information_schema.role_routine_grants where specific_schema='public' and routine_name like '%routine%manager%' and grantee in('PUBLIC','anon')),'045 manager RPCs not granted to public or anon');
select phase10k2_test.assert((select count(*)=7 from information_schema.role_routine_grants where specific_schema='public' and routine_name in('get_routine_manager_control_center','get_routine_foundation_editor_workspace','get_routine_template_editor_workspace','get_routine_template_version_diff','preview_routine_template_publication_batch','get_routine_reference_manager_workspace','get_routine_release_readiness') and grantee='authenticated'),'046 exact authenticated read grants installed');
select phase10k2_test.assert(not exists(select 1 from information_schema.role_table_grants where table_schema='public' and table_name like 'routine_%' and grantee='authenticated' and privilege_type in('INSERT','UPDATE','DELETE')),'047 no direct routine table DML grants');
select phase10k2_test.assert(exists(select 1 from pg_trigger where tgname='routine_phase10k2_location_guard_trigger' and not tgisinternal),'048 stable location guard installed');
select phase10k2_test.assert((select proconfig @> array['search_path=pg_catalog'] from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='get_routine_manager_control_center'),'049 manager RPC fixes search_path');
select phase10k2_test.assert(not exists(select 1 from public.routine_organization_settings where mode in('pilot','active')),'050 migration did not activate pilot or active');
select phase10k2_test.assert(to_regprocedure('public.set_routine_template_active(uuid,boolean,bigint,text,uuid)') is not null,'051 narrow template active RPC installed');
select phase10k2_test.assert((select (value->>'active')::boolean=false from phase10k2_test.state where key='template_deactivated'),'052 personal manager deactivated own organization template');
select phase10k2_test.assert((select (value->>'active')::boolean=true from phase10k2_test.state where key='template_reactivated'),'053 personal manager reactivated own organization template');
select phase10k2_test.assert((select value='true'::jsonb from phase10k2_test.state where key='staff_mutation_rejected'),'054 staff cannot change template active state');
select phase10k2_test.assert((select value='true'::jsonb from phase10k2_test.state where key='shared_mutation_rejected'),'055 shared operator cannot change template active state');
select phase10k2_test.assert((select value='true'::jsonb from phase10k2_test.state where key='cross_org_mutation_rejected'),'056 cross organization manager cannot change template active state');
select phase10k2_test.assert((select value='true'::jsonb from phase10k2_test.state where key='inactive_manager_rejected') and (select value='true'::jsonb from phase10k2_test.state where key='organizationless_manager_rejected'),'057 inactive and organizationless managers are rejected');
select phase10k2_test.assert((select value='true'::jsonb from phase10k2_test.state where key='reason_rejected'),'058 trimmed reason is required');
select phase10k2_test.assert((select (value->>'rejected')::boolean and (value->>'serverRevision')::bigint=(select (value->>'revision')::bigint from phase10k2_test.state where key='template_deactivated') from phase10k2_test.state where key='stale_rejected'),'059 expected revision and stale update are enforced');
select phase10k2_test.assert((select (replay.value-'idempotentReplay')=(original.value-'idempotentReplay') and (replay.value->>'idempotentReplay')::boolean from phase10k2_test.state replay join phase10k2_test.state original on original.key='template_deactivated' where replay.key='template_deactivate_replay'),'060 identical request replay returns the same result');
select phase10k2_test.assert((select value='true'::jsonb from phase10k2_test.state where key='changed_replay_rejected'),'061 reused key with changed request is rejected');
select phase10k2_test.assert((select (deactivated.value->>'revision')::bigint=(before.value->>'revision')::bigint+1 and (reactivated.value->>'revision')::bigint=(deactivated.value->>'revision')::bigint+1 from phase10k2_test.state before join phase10k2_test.state deactivated on deactivated.key='template_deactivated' join phase10k2_test.state reactivated on reactivated.key='template_reactivated' where before.key='template_active_before'),'062 each actual state change atomically increases revision');
select phase10k2_test.assert((select (after.value->>'updatedAt')::timestamptz>(before.value->>'updatedAt')::timestamptz and after.value->>'updatedBy'='11000000-0000-4000-8000-000000000001' from phase10k2_test.state before join phase10k2_test.state after on after.key='template_active_after' where before.key='template_active_before'),'063 updated time and actor are authoritative');
select phase10k2_test.assert((select after.value->>'publishedRowHash'=before.value->>'publishedRowHash' from phase10k2_test.state before join phase10k2_test.state after on after.key='template_active_after' where before.key='template_active_before'),'064 published version row remains immutable');
select phase10k2_test.assert((select (after.value->>'draftRowHash') is not distinct from (before.value->>'draftRowHash') from phase10k2_test.state before join phase10k2_test.state after on after.key='template_active_after' where before.key='template_active_before'),'065 active draft remains unchanged');
select phase10k2_test.assert((select after.value->>'currentPublishedVersionId'=before.value->>'currentPublishedVersionId' from phase10k2_test.state before join phase10k2_test.state after on after.key='template_active_after' where before.key='template_active_before'),'066 current published pointer remains unchanged');
select phase10k2_test.assert((select after.value->>'publishedContentHash'=before.value->>'publishedContentHash' from phase10k2_test.state before join phase10k2_test.state after on after.key='template_active_after' where before.key='template_active_before'),'067 published template content hash remains unchanged');
select phase10k2_test.assert((select after.value->>'runSnapshotState'=before.value->>'runSnapshotState' from phase10k2_test.state before join phase10k2_test.state after on after.key='template_active_after' where before.key='template_active_before'),'068 existing run and snapshot hashes remain unchanged');
select phase10k2_test.assert((select (after.value->>'runCount')::bigint=(before.value->>'runCount')::bigint and (after.value->>'taskCount')::bigint=(before.value->>'taskCount')::bigint from phase10k2_test.state before join phase10k2_test.state after on after.key='template_active_after' where before.key='template_active_before'),'069 activation changes create no run or task');
select phase10k2_test.assert((select value->'categories'->'templates'->'blockers' ? 'Published Opening template is inactive.' from phase10k2_test.state where key='readiness_inactive'),'070 inactive required Opening template is a readiness blocker');
select phase10k2_test.assert((select not (value->'categories'->'templates'->'blockers' ? 'Published Opening template is inactive.') from phase10k2_test.state where key='readiness_reactivated'),'071 reactivation removes the inactive Opening blocker');
select phase10k2_test.assert((select count(*)=2 from public.routine_ui_operations where operation_type='set_routine_template_active' and resource_type='routine_template'),'072 immutable UI operations record both actual manager requests');
select phase10k2_test.assert((select count(*)=2 from public.routine_operator_events where event_type='routine_template_active_changed'),'073 immutable Routine Engine events record both state changes');
select phase10k2_test.assert((select value='true'::jsonb from phase10k2_test.state where key='template_operation_immutable'),'074 template UI operations reject mutation');
select phase10k2_test.assert((select jsonb_array_length(value->'templates')>0 and (value->'templates'->0) ?& array['active','revision','updatedAt','updatedBy','hasCurrentPublishedVersion','hasActiveDraft','deactivationConsequence'] from phase10k2_test.state where key='control_center'),'075 manager template read model returns complete logical state');
select phase10k2_test.assert((select value->'templateStatus' ?& array['active','revision','updatedAt','updatedBy','hasCurrentPublishedVersion','hasActiveDraft','deactivationConsequence'] from phase10k2_test.state where key='editor'),'076 editor read model returns complete logical status');
select phase10k2_test.assert(not exists(select 1 from information_schema.role_routine_grants where specific_schema='public' and routine_name='set_routine_template_active' and grantee in('PUBLIC','anon')),'077 template active RPC is revoked from public and anon');
select phase10k2_test.assert((select count(*)=1 from information_schema.role_routine_grants where specific_schema='public' and routine_name='set_routine_template_active' and grantee='authenticated' and privilege_type='EXECUTE'),'078 template active RPC has one minimal authenticated execute grant');
select phase10k2_test.assert(not exists(select 1 from information_schema.role_table_grants where table_schema='public' and table_name like 'routine_%' and grantee='authenticated' and privilege_type in('INSERT','UPDATE','DELETE')),'079 no direct routine table DML introduced by completion patch');
select phase10k2_test.assert((select mode='shadow' from public.routine_organization_settings where organization_id='a1000000-0000-4000-8000-000000000001') and not exists(select 1 from public.routine_organization_settings where mode in('pilot','active')),'080 completion patch changes no engine mode');
